pred_sql:
SELECT count(*) 
FROM orders 
WHERE order_status = 'delivered';

SELECT ROUND(AVG(payment_installments)::numeric, 2) AS avg_installments
FROM order_payments
WHERE payment_type = 'credit_card';

SELECT 
    ROUND(
        100.0 * SUM(CASE WHEN review_score IN (1, 2) THEN 1 ELSE 0 END) / COUNT(*), 
        2
    ) AS percentage_low_reviews
FROM order_reviews;

SELECT count(*) 
FROM products 
WHERE product_category_name IS NULL;

SELECT 
    ROUND(
        100.0 * COUNT(CASE WHEN order_status = 'canceled' THEN 1 END) / COUNT(*), 
        2
    ) AS cancellation_rate_percentage
FROM orders;

SELECT 
    ROUND(
        CAST(
            AVG(EXTRACT(EPOCH FROM (order_approved_at - order_purchase_timestamp)) / 3600) 
            AS NUMERIC
        ), 
        2
    ) AS avg_hours_to_approval
FROM orders
WHERE order_approved_at IS NOT NULL;
